func buildXPEntryWhere[Q sqlite.Filterable](cols xpEntryColumns) xpEntryWhere[Q] {
	return xpEntryWhere[Q]{
		cols:        cols,
		ID:          sqlite.Where[Q, int64](cols.ID.Expression),
		CharacterID: sqlite.Where[Q, int64](cols.CharacterID.Expression),
		EntryDate:   sqlite.Where[Q, string](cols.EntryDate.Expression),
		Session:     sqlite.Where[Q, string](cols.Session.Expression),
		Reason:      sqlite.Where[Q, string](cols.Reason.Expression),
		Base:        sqlite.Where[Q, int64](cols.Base.Expression),
		Bonus:       sqlite.Where[Q, int64](cols.Bonus.Expression),
		R:           xpEntryWhereR[Q]{cols: cols},
	}
}

// xpEntryWhereR holds the relationship-based filters of
// xpEntryWhere under the R namespace — mirroring the model's
// R struct — so they cannot collide with column-based filter fields.
type xpEntryWhereR[Q sqlite.Filterable] struct {
	cols xpEntryColumns
}

// HasCharacter filters parents that have a matching Character using a
// correlated EXISTS subquery (semi-join). Unlike an INNER JOIN it does not
// multiply parent rows, so no DISTINCT is needed. The optional filters are
// applied to the subquery (i.e. to Characters).
func (w xpEntryWhereR[Q]) HasCharacter(filters ...bob.Mod[*dialect.SelectQuery]) mods.Where[Q] {
	q := sqlite.Select(
		sm.Columns(sqlite.Raw("1")),
		sm.From(Characters.NameExpr()),
		sm.Where(Characters.Columns.ID.EQ(w.cols.CharacterID)),
	)
	q.Apply(filters...)
	return mods.Where[Q]{E: sqlite.Exists(q)}
}

func (o *XPEntry) Preload(name string, retrieved any) error {
	if o == nil {
		return nil
	}

	switch name {
	case "Character":
		rel, ok := retrieved.(*Character)
		if !ok {
			return fmt.Errorf("xpEntry cannot load %T as %q", retrieved, name)
		}

		o.R.Character = rel
		o.R.Loaded.Character = true

		if rel != nil {
			rel.R.XPEntries = XPEntrySlice{o}
		}
		return nil
	default:
		return fmt.Errorf("xpEntry has no relationship %q", name)
	}
}

type xpEntryPreloader struct {
	Character func(...sqlite.PreloadOption) sqlite.Preloader
}

func buildXPEntryPreloader() xpEntryPreloader {
	return xpEntryPreloader{
		Character: func(opts ...sqlite.PreloadOption) sqlite.Preloader {
			return sqlite.Preload[*Character, CharacterSlice](sqlite.PreloadRel{
				Name: "Character",
				Sides: []sqlite.PreloadSide{
					{
						From:        XPEntries,
						To:          Characters,
						FromColumns: []string{"character_id"},
						ToColumns:   []string{"id"},
					},
				},
			}, Characters.Columns.Names(), characterScanMapperNullable, opts...)
		},
	}
}

type xpEntryThenLoader[Q orm.Loadable] struct {
	Character func(...bob.Mod[*dialect.SelectQuery]) orm.Loader[Q]
}

func buildXPEntryThenLoader[Q orm.Loadable]() xpEntryThenLoader[Q] {
	type CharacterLoadInterface interface {
		LoadCharacter(context.Context, bob.Executor, ...bob.Mod[*dialect.SelectQuery]) error
	}

	return xpEntryThenLoader[Q]{
		Character: thenLoadBuilder[Q](
			"Character",
			func(ctx context.Context, exec bob.Executor, retrieved CharacterLoadInterface, mods ...bob.Mod[*dialect.SelectQuery]) error {
				return retrieved.LoadCharacter(ctx, exec, mods...)
			},
		),
	}
}

// LoadCharacter loads the xpEntry's Character into the .R struct
func (o *XPEntry) LoadCharacter(ctx context.Context, exec bob.Executor, mods ...bob.Mod[*dialect.SelectQuery]) error {
	if o == nil {
		return nil
	}

	// Reset the relationship
	o.R.Character = nil
	o.R.Loaded.Character = false

	related, err := o.Character(mods...).One(ctx, exec)
	if err != nil {
		return err
	}

	related.R.XPEntries = XPEntrySlice{o}

	o.R.Character = related
	o.R.Loaded.Character = true
	return nil
}

// LoadCharacter loads the xpEntry's Character into the .R struct
func (os XPEntrySlice) LoadCharacter(ctx context.Context, exec bob.Executor, mods ...bob.Mod[*dialect.SelectQuery]) error {
	if len(os) == 0 {
		return nil
	}

	characters, err := os.Character(mods...).All(ctx, exec)
	if err != nil {
		return err
	}

	for _, o := range os {
		if o == nil {
			continue
		}

		o.R.Character = nil
		o.R.Loaded.Character = true
	}
	// O(N+M) stitch via a map keyed by the join column (key -> []parent; was O(N*M)).
	xpEntryByKey := make(map[int64][]*XPEntry, len(os))
	for _, o := range os {
		if o == nil {
			continue
		}

		xpEntryByKey[o.CharacterID] = append(xpEntryByKey[o.CharacterID], o)
	}

	for _, rel := range characters {

		owners, ok := xpEntryByKey[rel.ID]
		if !ok {
			continue
		}

		for _, o := range owners {

			// to-one: keep only the first matching child (matches the previous break)
			if o.R.Character != nil {
				continue
			}

			rel.R.XPEntries = append(rel.R.XPEntries, o)

			o.R.Character = rel

		}
	}

	return nil
}

type xpEntryJoins[Q dialect.Joinable] struct {
	typ       string
	Character modAs[Q, characterColumns]
}

func (j xpEntryJoins[Q]) aliasedAs(alias string) xpEntryJoins[Q] {
	return buildXPEntryJoins[Q](buildXPEntryColumns(alias), j.typ)
}

func buildXPEntryJoins[Q dialect.Joinable](cols xpEntryColumns, typ string) xpEntryJoins[Q] {
	return xpEntryJoins[Q]{
		typ: typ,
		Character: modAs[Q, characterColumns]{
			c: Characters.Columns,
			f: func(to characterColumns) bob.Mod[Q] {
				mods := make(mods.QueryMods[Q], 0, 1)

				{
					mods = append(mods, dialect.Join[Q](typ, Characters.NameExpr().As(to.Alias())).On(
						to.ID.EQ(cols.CharacterID),
					))
				}

				return mods
			},
		},
	}
}
